recipes.code:
{
  "inputs": [
    {
      "id": "serpagent-api-key",
      "type": "promptString",
      "description": "SERP Agent API key (sk_...). Free sandbox key: POST https://serp-agent.com/v1/accounts",
      "password": true
    }
  ],
  "servers": {
    "seo": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "serpagent-mcp@1.0.1"
      ],
      "env": {
        "SERPAGENT_API_KEY": "${input:serpagent-api-key}"
      }
    }
  }
}
